// Slack signs the exact bytes it sends, so the database check gets those bytes (base64), never a re-encoded form,
// with Slack's two headers. Over 256 KiB (a real click or pop-up is a few KiB) the body is left out, so the check
// refuses it. Missing parts become empty text, which the check refuses too.
const item = $input.first();
const headers = item.json.headers ?? {};
let bodyB64 = '';
if (item.binary?.data) {
  const body = await this.helpers.getBinaryDataBuffer(0, 'data');
  if (body.length <= 262144) bodyB64 = body.toString('base64');
}
return [{ json: {
  timestamp: String(headers['x-slack-request-timestamp'] ?? ''),
  signature: String(headers['x-slack-signature'] ?? ''),
  body_b64: bodyB64,
} }];

parameters.query:
-- Is this click from Slack? true only for a body Slack signed with our secret within 5 minutes (migration 016);
-- false for anything else. An error here (no secret set, database trouble) takes the "can't check" path.
-- Values in order: 1 timestamp header, 2 signature header, 3 the body exactly as sent (base64)
select verify_slack_request($1, $2, $3) as verified;

parameters.jsCode:
// The click itself, read from the same bytes the database just checked: form data with one "payload" field holding
// a JSON object. Anything else ends the run quietly (Slack already got its answer). Read by hand: n8n's code
// sandbox has no URLSearchParams. In form data "+" is a space, and %XX is a byte of UTF-8 text.
const body = Buffer.from($('Read body').first().json.body_b64, 'base64').toString('utf8');
const decode = (text) => decodeURIComponent(text.replace(/\+/g, ' '));
const payloads = [];
for (const pair of body.split('&')) {
  const at = pair.indexOf('=');
  let name;
  let value;
  try {
    name = decode(at < 0 ? pair : pair.slice(0, at));
    value = decode(at < 0 ? '' : pair.slice(at + 1));
  } catch {
    return []; // a broken %XX
  }
  if (name === 'payload') payloads.push(value);
}
if (payloads.length !== 1) return [];
let click;
try {
  click = JSON.parse(payloads[0]);
} catch {
  return [];
}
if (!click || typeof click !== 'object' || Array.isArray(click)) return [];
return [{ json: click }];

// The database couldn't check the click (no secret set, or the database is in trouble). Slack has shown the clicker
// an error; failing here sends the Alerts workflow's message to #support-alerts. Nothing was done.
throw new Error("Button clicks can't be checked right now (the database check failed), so nothing was done. " +
  'Slack showed the clicker an error. See docs/SETUP.md section 9 (Slack signing secret).');

// What did the support person click, and may they? Only a click the database confirmed as genuinely from Slack gets
// here. Returns one item with a "kind": open_edit, decide (approve, send an edit, take over), open_limit and
// set_limit (the "Change limit" button on a limit alert, then its pop-up) or not_staff.
// Anything else (an unknown button, a malformed click) returns nothing, which ends the run quietly.
const s = $('Settings').first().json;
for (const [name, value] of Object.entries(s)) {
  if (!String(value ?? '').trim() || String(value).startsWith('PASTE_')) {
    throw new Error(`Settings: ${name} is not filled in. Nothing was done.`);
  }
}
const p = $('Parse click').first().json; // the click, from the bytes the database verified
const user = p.user?.id ?? '';
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const CLIENT_KEY = /^[a-z0-9][a-z0-9-]{0,63}$/;
if (!/^[UW][A-Z0-9]{2,}$/.test(user)) return [];

let click;
if (p.type === 'block_actions' && p.actions?.[0]?.action_id === 'change_limit') {
  const clientKey = p.actions[0].value ?? '';
  if (!CLIENT_KEY.test(clientKey)) return [];
  click = { action: 'open_limit', client_key: clientKey, trigger_id: p.trigger_id ?? '' };
} else if (p.type === 'block_actions') {
  const a = p.actions?.[0] ?? {};
  const statusFor = { approve: 'approved', take_over: 'taken_over', edit: '' };
  if (!(a.action_id in statusFor) || !UUID.test(a.value ?? '')) return [];
  click = { action: a.action_id, draft_id: a.value, status: statusFor[a.action_id], trigger_id: p.trigger_id ?? '', reply: '' };
} else if (p.type === 'view_submission' && p.view?.callback_id === 'edit_reply') {
  const draftId = p.view.private_metadata ?? '';
  const reply = String(p.view.state?.values?.reply?.reply_text?.value ?? '').trim();
  if (!UUID.test(draftId) || !reply) return [];
  click = { action: 'send_edit', draft_id: draftId, status: 'edited', trigger_id: '', reply };
} else if (p.type === 'view_submission' && p.view?.callback_id === 'change_limit') {
  // Slack's number box already allows only 1 to 200; checked again here and once more in the database.
  const clientKey = p.view.private_metadata ?? '';
  const limit = String(p.view.state?.values?.limit?.limit_value?.value ?? '').trim();
  if (!CLIENT_KEY.test(clientKey) || !/^\d{1,3}$/.test(limit) || +limit < 1 || +limit > 200) return [];
  click = { action: 'set_limit', client_key: clientKey, new_limit: Number(limit) };
} else {
  return [];
}

const kindFor = { edit: 'open_edit', open_limit: 'open_limit', set_limit: 'set_limit' };
const kind = !$('Check staff').first().json.is_staff ? 'not_staff' : kindFor[click.action] ?? 'decide';
// Notes to the person who clicked go where they clicked: limit alerts sit in the alerts channel.
const replyChannel = click.action in { open_limit: 1, set_limit: 1 } ? s.alerts_channel : s.support_queue_channel;
return [{ json: { kind, user_id: user, queue_channel: s.support_queue_channel, reply_channel: replyChannel, ...click } }];

// The edit box: the draft's reply, ready to change. Sending it comes back here as a "view_submission" click.
const click = $('Read click').first().json;
const view = {
  type: 'modal',
  callback_id: 'edit_reply',
  private_metadata: click.draft_id, // which draft the edited reply belongs to
  title: { type: 'plain_text', text: 'Edit the reply' },
  submit: { type: 'plain_text', text: 'Send to client' },
  close: { type: 'plain_text', text: 'Cancel' },
  blocks: [
    {
      type: 'input',
      block_id: 'reply',
      label: { type: 'plain_text', text: 'Reply to the client' },
      element: {
        type: 'plain_text_input',
        action_id: 'reply_text',
        multiline: true,
        max_length: 3000,
        initial_value: $input.first().json.reply,
      },
    },
    { type: 'context', elements: [{ type: 'mrkdwn', text: "Goes to the client's thread when you press Send." }] },
  ],
};
return [{ json: { body: JSON.stringify({ trigger_id: click.trigger_id, view }) } }];

// Slack answers "ok": false instead of an error code when it refuses, so check it here and fail loudly.
const r = $input.first().json;
if (!r.ok) throw new Error(`Slack refused to open the pop-up: ${r.error ?? 'no reason given'}`);
return [];

// The card once a person has decided: everything it showed, minus the buttons, plus who did what. If Slack didn't
// return the card, a short version takes its place.
const d = $('Decide').first().json;
if (!d.queue_ts) return []; // no card on record, so nothing to update
const who = `<@${$('Read click').first().json.user_id}>`;

const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const MAX = 2900; // Slack allows 3000 characters per section
const cut = (t) => (t.length > MAX ? t.slice(0, MAX - 1) + '…' : t);
const quote = (t) => esc(t).split('\n').map((line) => '> ' + line).join('\n');

const res = $input.first().json; // Slack's copy of the card
const found = res.ok && res.messages?.[0]?.ts === d.queue_ts ? (res.messages[0].blocks ?? []) : [];
const blocks = found.filter((b) => b.type !== 'actions');
if (!blocks.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*🎫 ${esc(d.display_name)}*` } });

const outcome = {
  approved: `:white_check_mark: *Approved and sent* by ${who}`,
  edited: `:pencil2: *Edited and sent* by ${who}`,
  taken_over: `:raising_hand: *Taken over* by ${who}, who will answer the client.`,
}[d.status];
if (d.status === 'edited') {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: cut(`*Reply sent (edited):*\n${quote(d.sent_reply)}`) } });
}
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: outcome }] });
const notice = { approved: 'Approved and sent', edited: 'Edited and sent', taken_over: 'Taken over by a person' }[d.status];
return [{ json: { text: notice, blocks: JSON.stringify({ blocks }) } }];

// The solved ticket, saved for the agent's "similar past tickets" search: what was wrong, how it was fixed and what
// the client was told. The client's own message isn't saved (it can hold names). save_past_ticket also refuses any
// text that still holds an email address or a phone number.
const d = $('Decide').first().json;
const s = $('Settings').first().json;
const steps = (Array.isArray(d.fix_steps) ? d.fix_steps : []).map((x, i) => `${i + 1}. ${x}`).join('\n');
const title = String(d.likely_cause ?? '').split(/(?<=[.!?])\s/)[0].slice(0, 150) || 'Solved ticket';
const content = `Cause: ${d.likely_cause}\n\nFix:\n${steps || '(no steps recorded)'}\n\nReply sent to the client:\n${d.sent_reply}`;
const url = `${s.slack_workspace_url.replace(/\/+$/, '')}/archives/${d.channel_id}/p${d.thread_ts.replace('.', '')}`;
return [{ json: { ticket_id: d.ticket_id, title, content, url } }];

parameters.query:
-- Save the solved ticket for the agent's search, through the one function that forces the "past_ticket" label
-- and refuses emails and phone numbers (migration 004). It takes the approved draft's id and refuses a draft the agent marked as naming a customer (015).
select save_past_ticket($1::uuid, $2, $3, $4, $5::vector) as saved;

parameters.jsCode:
// The "Change limit" pop-up. Slack's number box accepts only a whole number from 1 to 200. Saving comes back
// here as a "view_submission" click, and the database checks the number again.
const click = $('Read click').first().json;
const c = $input.first().json;
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const view = {
  type: 'modal',
  callback_id: 'change_limit',
  private_metadata: click.client_key, // which client the new limit is for
  title: { type: 'plain_text', text: 'Change the limit' },
  submit: { type: 'plain_text', text: 'Save' },
  close: { type: 'plain_text', text: 'Cancel' },
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: `*${esc(c.display_name)}* can have *${c.drafts_per_hour}* drafts an hour.` } },
    {
      type: 'input',
      block_id: 'limit',
      label: { type: 'plain_text', text: 'New limit (drafts per hour)' },
      element: {
        type: 'number_input',
        action_id: 'limit_value',
        is_decimal_allowed: false,
        min_value: '1',
        max_value: '200',
        initial_value: String(Math.min(c.drafts_per_hour, 200)), // the admin may have set more than Slack allows here
      },
    },
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Applies at once and is logged with your name.' }] },
  ],
};
return [{ json: { body: JSON.stringify({ trigger_id: click.trigger_id, view }) } }];

parameters.query:
-- Staff saved a new limit in the pop-up. The database accepts only a known client and 1 to 200, and logs who
-- changed it, when, and the old and new number.
select * from set_draft_limit($1, $2::integer, $3);
